    """
    global _publisher
    if _publisher is None:
        config = settings.KAFKA_TOPICS.get(settings.KAFKA_REGION_TO_CONTROL)
        _publisher = KafkaProducer(
            kafka_config.get_kafka_producer_cluster_options(config["cluster"])
